import{_ as a,c as s,aU as i,a as n}from"./chunks/framework.DIXiA2XH.js";const g=JSON.parse('{"title":"kafka的消息模式","description":"","frontmatter":{},"headers":[],"relativePath":"note/back-end/kafka/kafka的消息模式.md","filePath":"note/back-end/kafka/kafka的消息模式.md","lastUpdated":1772976918000}'),r={name:"note/back-end/kafka/kafka的消息模式.md"};function e(l,t,o,d,p,h){return n(),s("div",null,[...t[0]||(t[0]=[i(`<h1 id="kafka的消息模式" tabindex="-1">kafka的消息模式 <a class="header-anchor" href="#kafka的消息模式" aria-label="Permalink to &quot;kafka的消息模式&quot;">​</a></h1><p>kafka是一种 <strong>基于消费者组（Consumer Group）的分布式流处理模型</strong>，既支持“广播”，也支持“负载均衡”，但默认行为是 <strong>负载均衡（竞争消费）</strong>。</p><hr><h2 id="✅-kafka-的两种主要消费模式" tabindex="-1">✅ Kafka 的两种主要消费模式 <a class="header-anchor" href="#✅-kafka-的两种主要消费模式" aria-label="Permalink to &quot;✅ Kafka 的两种主要消费模式&quot;">​</a></h2><h4 id="_1️⃣-负载均衡模式-competing-consumers-——默认模式" tabindex="-1">1️⃣ <strong>负载均衡模式（Competing Consumers）——默认模式</strong> <a class="header-anchor" href="#_1️⃣-负载均衡模式-competing-consumers-——默认模式" aria-label="Permalink to &quot;1️⃣ **负载均衡模式（Competing Consumers）——默认模式**&quot;">​</a></h4><ul><li>多个消费者属于 <strong>同一个消费者组（Consumer Group）</strong></li><li>它们<strong>共同消费一个 Topic 的消息</strong></li><li>每条消息只会被<strong>组内的一个消费者</strong>消费（类似“队列”）</li><li>用于 <strong>横向扩展、提高吞吐量</strong></li></ul><p>📌 <strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 消费者 A 和 B 属于同一个 group</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin\\windows\\kafka-console-consumer.bat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-topic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-group</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin\\windows\\kafka-console-consumer.bat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-topic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-group</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>✅ 结果：</p><ul><li>消息 1 → 消费者 A</li><li>消息 2 → 消费者 B</li><li>消息 3 → 消费者 A</li><li>……</li></ul><p>👉 <strong>每条消息只被消费一次</strong>，A 和 B <strong>竞争消费</strong>。</p><hr><h4 id="_2️⃣-广播模式-broadcast-——通过不同消费者组实现" tabindex="-1">2️⃣ <strong>广播模式（Broadcast）——通过不同消费者组实现</strong> <a class="header-anchor" href="#_2️⃣-广播模式-broadcast-——通过不同消费者组实现" aria-label="Permalink to &quot;2️⃣ **广播模式（Broadcast）——通过不同消费者组实现**&quot;">​</a></h4><ul><li>多个消费者属于 <strong>不同的消费者组</strong></li><li>每个组都会<strong>独立、完整地消费 Topic 的所有消息</strong></li><li>实现“一条消息被多个客户端收到”</li></ul><p>📌 <strong>示例</strong>：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 消费者 A 属于 group-a</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin\\windows\\kafka-console-consumer.bat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-topic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> group-a</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 消费者 B 属于 group-b（不同组！）</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">bin\\windows\\kafka-console-consumer.bat</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --topic</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> my-topic</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --bootstrap-server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> localhost:9092</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> group-b</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><p>✅ 结果：</p><ul><li>消息 1 → A 收到，B 也收到</li><li>消息 2 → A 收到，B 也收到</li><li>……</li></ul><p>👉 <strong>实现了广播</strong>：每个消费者组都收到全部消息。</p><hr><h3 id="📊-对比总结" tabindex="-1">📊 对比总结 <a class="header-anchor" href="#📊-对比总结" aria-label="Permalink to &quot;📊 对比总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>模式</th><th>消费者组</th><th>消息分发方式</th><th>类比</th></tr></thead><tbody><tr><td><strong>负载均衡</strong></td><td>同一个组</td><td>每条消息只被组内一个消费者消费</td><td>多个工人分拣快递（每人分几件）</td></tr><tr><td><strong>广播</strong></td><td>不同组</td><td>每个组都收到全部消息</td><td>所有工人都收到同一份通知</td></tr></tbody></table><hr><h3 id="✅-回答你的问题" tabindex="-1">✅ 回答你的问题 <a class="header-anchor" href="#✅-回答你的问题" aria-label="Permalink to &quot;✅ 回答你的问题&quot;">​</a></h3><blockquote><p><strong>“kafka集群，都是广播模式么？只有这一种模式？”</strong></p></blockquote><p>❌ 不是。Kafka <strong>默认不是广播模式</strong>，而是<strong>负载均衡模式</strong>。</p><blockquote><p><strong>“其他客户端监听同一个topic，都可以收到消息？”</strong></p></blockquote><p>❌ 不一定！关键看 <strong>是否在同一个消费者组</strong>：</p><ul><li>✅ 如果 <strong>消费者组不同</strong> → 每个组都能收到全部消息（广播）</li><li>❌ 如果 <strong>消费者组相同</strong> → 消息会被组内消费者“瓜分”（负载均衡）</li></ul><hr><h3 id="🚀-如何实现-所有客户端都收到消息" tabindex="-1">🚀 如何实现“所有客户端都收到消息”？ <a class="header-anchor" href="#🚀-如何实现-所有客户端都收到消息" aria-label="Permalink to &quot;🚀 如何实现“所有客户端都收到消息”？&quot;">​</a></h3><p>如果你想让 <strong>多个客户端都收到相同的消息</strong>（广播），你就需要：</p><p>👉 <strong>让每个客户端使用不同的 <code>--group</code> 名称</strong>。</p><p>例如：</p><div class="language-bash vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 客户端1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client-1</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 客户端2</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client-2</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 客户端3</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">--group</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> client-3</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br></div></div><p>这样，三个客户端都会收到 <code>my-topic</code> 的全部消息。</p><hr><h3 id="💡-补充-如果不指定-group" tabindex="-1">💡 补充：如果不指定 <code>--group</code>？ <a class="header-anchor" href="#💡-补充-如果不指定-group" aria-label="Permalink to &quot;💡 补充：如果不指定 \`--group\`？&quot;">​</a></h3><ul><li>Kafka 会自动生成一个随机的消费者组 ID。</li><li>每次启动都是<strong>不同的组</strong>，所以每次都会从头消费（<code>--from-beginning</code> 效果）。</li><li>这种情况下，<strong>看起来像广播</strong>，但其实是“每个消费者都是独立组”。</li></ul><hr><h3 id="✅-总结" tabindex="-1">✅ 总结 <a class="header-anchor" href="#✅-总结" aria-label="Permalink to &quot;✅ 总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>Kafka 是广播模式吗？</td><td>❌ 不是，默认是负载均衡</td></tr><tr><td>所有客户端都能收到消息吗？</td><td>❌ 只有<strong>不同消费者组</strong>才能收到全部消息</td></tr><tr><td>如何实现广播？</td><td>让每个消费者使用<strong>不同的 <code>--group</code></strong></td></tr><tr><td>如何实现竞争消费？</td><td>多个消费者使用<strong>相同的 <code>--group</code></strong></td></tr></tbody></table><p>Kafka 的这种设计非常灵活，既能做“消息队列”，也能做“事件广播”，是它强大之处 🚀</p><h2 id="分区和消费者的关系" tabindex="-1">分区和消费者的关系 <a class="header-anchor" href="#分区和消费者的关系" aria-label="Permalink to &quot;分区和消费者的关系&quot;">​</a></h2><blockquote><p>✅ <strong>在同一个消费者组（Consumer Group）中，一个分区（Partition）只能被一个消费者（Consumer）消费。</strong></p></blockquote><hr><p>Kafka 的消费顺序和分配机制，<strong>不是按消息一条条“轮着来”或“抢着来”</strong>，而是基于 <strong>Topic 的分区（Partition）</strong> 来决定的。</p><hr><h3 id="🧩-核心机制-分区-partition-是分配的最小单位" tabindex="-1">🧩 核心机制：分区（Partition）是分配的最小单位 <a class="header-anchor" href="#🧩-核心机制-分区-partition-是分配的最小单位" aria-label="Permalink to &quot;🧩 核心机制：分区（Partition）是分配的最小单位&quot;">​</a></h3><ol><li>一个 Topic 有多个 <strong>分区（Partitions）</strong></li><li>每个分区内的消息是<strong>严格有序</strong>的</li><li>每个分区只能被<strong>同一个消费者组中的一个消费者</strong>消费</li><li>消费者组内的消费者会<strong>瓜分这些分区</strong></li></ol><hr><h3 id="📊-举个例子" tabindex="-1">📊 举个例子 <a class="header-anchor" href="#📊-举个例子" aria-label="Permalink to &quot;📊 举个例子&quot;">​</a></h3><p>假设：</p><ul><li>Topic: <code>my-topic</code></li><li>分区数: 3（Partition 0, 1, 2）</li><li>消费者组: <code>my-group</code></li><li>启动 2 个消费者：<code>Consumer A</code> 和 <code>Consumer B</code></li></ul><p>Kafka 会进行 <strong>分区再平衡（Rebalance）</strong>，可能分配如下：</p><table tabindex="0"><thead><tr><th>分区</th><th>消费者</th></tr></thead><tbody><tr><td>Partition 0</td><td>Consumer A</td></tr><tr><td>Partition 1</td><td>Consumer B</td></tr><tr><td>Partition 2</td><td>Consumer A</td></tr></tbody></table><blockquote><p>注意：具体分配由 Kafka 的 <strong>分区分配策略</strong>（如 Range、RoundRobin、Sticky）决定。</p></blockquote><hr><h3 id="✅-消费行为" tabindex="-1">✅ 消费行为 <a class="header-anchor" href="#✅-消费行为" aria-label="Permalink to &quot;✅ 消费行为&quot;">​</a></h3><ul><li>所有发往 <strong>Partition 0 和 2</strong> 的消息 → 只由 <strong>A</strong> 消费</li><li>所有发往 <strong>Partition 1</strong> 的消息 → 只由 <strong>B</strong> 消费</li><li><strong>A 和 B 同时独立消费</strong>，互不干扰</li></ul><hr><h3 id="🔄-细节" tabindex="-1">🔄 细节 <a class="header-anchor" href="#🔄-细节" aria-label="Permalink to &quot;🔄 细节&quot;">​</a></h3><ul><li>消息在<strong>生产时</strong>就被分配到某个分区（默认轮询，或按 Key 哈希）</li><li>哪个消费者负责这个分区，就由谁消费</li><li>即使 A 很忙，B 很空闲，<strong>A 负责的分区也不会交给 B</strong></li></ul><hr><h3 id="🎯-举个实际例子" tabindex="-1">🎯 举个实际例子 <a class="header-anchor" href="#🎯-举个实际例子" aria-label="Permalink to &quot;🎯 举个实际例子&quot;">​</a></h3><p>生产者发送 6 条消息：</p><table tabindex="0"><thead><tr><th>消息</th><th>分区</th><th>内容</th></tr></thead><tbody><tr><td>M1</td><td>0</td><td>Hello</td></tr><tr><td>M2</td><td>1</td><td>World</td></tr><tr><td>M3</td><td>0</td><td>Kafka</td></tr><tr><td>M4</td><td>2</td><td>is</td></tr><tr><td>M5</td><td>1</td><td>cool</td></tr><tr><td>M6</td><td>2</td><td>!</td></tr></tbody></table><p>消费者分配：</p><ul><li>A: P0, P2</li><li>B: P1</li></ul><p>消费顺序可能是：</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Consumer A: Hello → Kafka → is → !</span></span>
<span class="line"><span>Consumer B: World → cool</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>虽然 M2（World）在 M3（Kafka）之前发送，但因为它们在不同分区，所以 A 和 B 是并行消费的，<strong>整体顺序不保证</strong>。</p><hr><h3 id="✅-如何保证顺序" tabindex="-1">✅ 如何保证顺序？ <a class="header-anchor" href="#✅-如何保证顺序" aria-label="Permalink to &quot;✅ 如何保证顺序？&quot;">​</a></h3><table tabindex="0"><thead><tr><th>需求</th><th>实现方式</th></tr></thead><tbody><tr><td><strong>分区内有序</strong></td><td>默认支持，无需配置</td></tr><tr><td><strong>全局有序（所有消息）</strong></td><td>Topic 只能有 <strong>1 个分区</strong>，所有消息串行处理</td></tr><tr><td><strong>按 Key 有序</strong></td><td>生产者使用 <code>key</code>，相同 key 的消息会进入同一分区，保证该 key 的消息有序</td></tr></tbody></table><hr><h3 id="🚨-注意-消费者数量-vs-分区数" tabindex="-1">🚨 注意：消费者数量 vs 分区数 <a class="header-anchor" href="#🚨-注意-消费者数量-vs-分区数" aria-label="Permalink to &quot;🚨 注意：消费者数量 vs 分区数&quot;">​</a></h3><ul><li>如果消费者数量 &gt; 分区数：<strong>多余的消费者会空闲</strong>（没有分区可分配）</li><li>如果消费者数量 ≤ 分区数：可以充分利用并行消费</li></ul><hr><h3 id="✅-总结-1" tabindex="-1">✅ 总结 <a class="header-anchor" href="#✅-总结-1" aria-label="Permalink to &quot;✅ 总结&quot;">​</a></h3><table tabindex="0"><thead><tr><th>问题</th><th>答案</th></tr></thead><tbody><tr><td>消费是轮着来吗？</td><td>❌ 不是，是基于<strong>分区分配</strong></td></tr><tr><td>谁快谁消费更多？</td><td>❌ 不是，每个消费者固定负责某些分区</td></tr><tr><td>消息是严格顺序的吗？</td><td>✅ <strong>分区内有序</strong>，❌ <strong>Topic 级别不保证全局有序</strong></td></tr><tr><td>如何实现负载均衡？</td><td>多个分区 + 多个消费者，每个消费者处理一个或多个分区</td></tr></tbody></table><hr><h3 id="💡-记住一句话" tabindex="-1">💡 记住一句话： <a class="header-anchor" href="#💡-记住一句话" aria-label="Permalink to &quot;💡 记住一句话：&quot;">​</a></h3><blockquote><p><strong>“Kafka 的并行度 = 分区数”</strong><br> 消费者只能消费<strong>整个分区</strong>，不能“抢”单条消息。</p></blockquote><p>这就是 Kafka 高吞吐、可扩展的核心设计 🚀</p>`,85)])])}const c=a(r,[["render",e]]);export{g as __pageData,c as default};
